import{_ as p,a0 as o,w as d,s as r,I as s,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 终端管理你的日历 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 终端管理你的日历 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 终端管理你的日历 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 终端管理你的日历 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command","title":"在 Linux 终端管理你的日历","tag":"202204","desc":""},"relativePath":"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command.md","filePath":"[post].md"}'),u={name:"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command.md"};function k(m,a,g,c,h,f){const e=o("Link");return d(),r("div",null,[a[27]||(a[27]=s("h1",{id:"在-linux-终端管理你的日历",tabindex:"-1"},[n("在 Linux 终端管理你的日历 "),s("a",{class:"header-anchor",href:"#在-linux-终端管理你的日历","aria-label":"Permalink to “在 Linux 终端管理你的日历”"},"​")],-1)),a[28]||(a[28]=s("blockquote",null,[s("p",null,"KDE 很适合在 Linux 上进行基于终端的日程安排。konsolekalendar 命令让你从终端查看和管理 iCal 日历。")],-1)),a[29]||(a[29]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/18/161418rsp7x2evo6zl766v.jpg",alt:""})],-1)),s("p",null,[a[1]||(a[1]=n("我是一个 ",-1)),l(e,{href:"https://opensource.com/article/17/5/7-cool-kde-tweaks-will-improve-your-life"},{default:i(()=>[...a[0]||(a[0]=[n("KDE 用户",-1)])]),_:1}),a[2]||(a[2]=n("，多年来我一直在 Plasma 桌面上进行着看似无尽的探索。如果你在公开场合问我，我可能会声称自己对我每天使用的桌面了如指掌。但实际上，我只是刚刚触及到表面而已。似乎每天我都能学到一个新的 KDE 技巧，让我的生活变得更轻松或更有趣，我最新的发现是 ",-1)),a[3]||(a[3]=s("code",null,"konsolekalendar",-1)),a[4]||(a[4]=n(" 命令，它让你从终端查看和管理 iCal 日历。",-1))]),a[30]||(a[30]=t('<h3 id="akonadi" tabindex="-1">Akonadi <a class="header-anchor" href="#akonadi" aria-label="Permalink to “Akonadi”">​</a></h3><p>Akonadi 项目是一个底层 KDE 框架，帮助 Plasma 桌面跟踪所有的个人信息管理器（PIM）数据。它主要是为开发者服务的，包括很多可以让程序员用来创建应用的库，通过这些程序你可以访问你的联系人、笔记、电子邮件、日历等等。Akonadi 中包括一些终端命令，比如 <code>akonadictl</code> 可以启动和停止 Akonadi 服务，但它们大多是为了排除故障。然而，<code>konsolekalendar</code> 是一个面向用户的命令，可以让你完全访问 Kontact 套件的所有数据，包括 KMail、Notes 和日历。</p><p>如果你正在运行 KDE 的 Plasma 桌面，那么你已经安装了 Kontact 套件。</p><p><img src="https://opensource.com/sites/default/files/uploads/kontact.jpg" alt="Kontact UI" title="Kontact UI"></p><p>你也安装好了 Akonadi 和它的工具，所以你所需要的基于终端的日历完成了!</p><h3 id="从终端查看你的日历" tabindex="-1">从终端查看你的日历 <a class="header-anchor" href="#从终端查看你的日历" aria-label="Permalink to “从终端查看你的日历”">​</a></h3>',6)),s("p",null,[a[7]||(a[7]=n("由于 ",-1)),l(e,{href:"https://opensource.com/article/21/1/nextcloud-productivity"},{default:i(()=>[...a[5]||(a[5]=[n("NextCloud",-1)])]),_:1}),a[8]||(a[8]=n(" 和 ",-1)),l(e,{href:"https://radicale.org/v3.html"},{default:i(()=>[...a[6]||(a[6]=[n("Radicale",-1)])]),_:1}),a[9]||(a[9]=n(" 等项目的存在，你可以托管自己的 iCal 日历服务，或者你可能已经在流行的供应商（例如，Google）那里拥有一个 iCal 账户。当你使用 Kontact 管理日历时，你订阅了一个日历对象（用 Akonadi 的术语说是一个“",-1)),a[10]||(a[10]=s("ruby",null,[n("集合"),s("rt",null,"collection")],-1)),a[11]||(a[11]=n("”）。当你对你的本地日历进行更新时，这些变化会被送回你的 iCal 服务器以同步你的日历服务器和客户端。",-1))]),a[31]||(a[31]=t(`<p>无论你是否使用过 Kontact 的日历功能，你在 Kontact 中都有一些默认的日历对象。你有一个叫<strong>个人日历</strong>和<strong>生日和纪念日</strong>的日历对象。</p><p>以下是如何显示当天的日历（默认为<strong>个人日历</strong>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        10:00 AM - 11:00 AM</span></span>
<span class="line"><span>Summary: Covid booster shot</span></span>
<span class="line"><span>UID: 8d8a1e38-c88c-4d84-99e5-23...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        12:00 PM - 01:00 PM</span></span>
<span class="line"><span>Summary: Lunch</span></span>
<span class="line"><span>UID: 7aa89a...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        01:00 PM - 04:45 PM</span></span>
<span class="line"><span>Summary: Afternoon coding</span></span>
<span class="line"><span>UID: 9cde38b...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        06:00 PM - 10:00 PM</span></span>
<span class="line"><span>Summary: Planescape game</span></span>
<span class="line"><span>UID: c73f7e98-722f-48a2-8006-66...</span></span>
<span class="line"><span>----------------------------------</span></span></code></pre></div><h3 id="添加一个事件" tabindex="-1">添加一个事件 <a class="header-anchor" href="#添加一个事件" aria-label="Permalink to “添加一个事件”">​</a></h3><p>要查看你订阅的所有日历，请使用 <code>--list-calendars</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --list-calendars</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>3  - (Read only) Birthdays &amp; Anniversaries</span></span>
<span class="line"><span>11 - Personal Calendar</span></span>
<span class="line"><span>60 - (Read only) Open Invitations</span></span>
<span class="line"><span>61 - (Read only) Declined Invitations</span></span>
<span class="line"><span>66 - Dnd</span></span>
<span class="line"><span>67 - Work</span></span>
<span class="line"><span>68 - Museum</span></span></code></pre></div><p>左边的数字是日历的 ID。要添加一个事件到一个特定的日历，请使用 <code>--calendar</code> 选项，然后是日历 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --add --calendar 66 \\</span></span>
<span class="line"><span>--date 2022-01-16 \\</span></span>
<span class="line"><span>--time 20:00 --end-time 23:59 \\</span></span>
<span class="line"><span>--summary &quot;Another game&quot; \\</span></span>
<span class="line"><span>--description &quot;Remember to bring dice&quot; \\</span></span>
<span class="line"><span>Success: &quot;Another game&quot; inserted</span></span></code></pre></div><h3 id="删除一个事件" tabindex="-1">删除一个事件 <a class="header-anchor" href="#删除一个事件" aria-label="Permalink to “删除一个事件”">​</a></h3><p>你也可以删除事件。每个事件都有一个唯一的 ID（UID），在每个事件列表的底部提供：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --list</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        06:00 PM - 10:00 PM</span></span>
<span class="line"><span>Summary: Planescape game</span></span>
<span class="line"><span>UID: c73f7e98-722f-48a2-8006-66aa8ddcf789</span></span></code></pre></div><p>要删除一个事件，请使用 <code>--delete</code> 选项，同时使用 <code>--uid</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --delete \\</span></span>
<span class="line"><span>--uid c73f7e98-722f-48a2-8006-66aa8ddcf789</span></span></code></pre></div><h3 id="终端中的-akonadi" tabindex="-1">终端中的 Akonadi <a class="header-anchor" href="#终端中的-akonadi" aria-label="Permalink to “终端中的 Akonadi”">​</a></h3><p>你用 <code>konsolekalendar</code> 所做的一切都会立即在 Akonadi 中执行，并在 Kontact 中得到同样快的反映。使用一个并不意味着你必须放弃另一个。由于它们共享 Akonadi 后端，两者查看和编辑相同的数据。<code>konsolekalendar</code> 命令是一项正在进行的工作。未来的计划包括与 Kontact 的笔记和日记部分的整合，而且还有很多比本文所涉及的更多的选项。如果你在使用 KDE 桌面，试试 <code>konsolekalendar</code>，体验一下终端的 PIM！</p><hr>`,16)),s("p",null,[a[13]||(a[13]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/22/2/manage-calendar-linux-konsolekalender-kde"},{default:i(()=>[...a[12]||(a[12]=[n("https://opensource.com/article/22/2/manage-calendar-linux-konsolekalender-kde",-1)])]),_:1})]),s("p",null,[a[18]||(a[18]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...a[14]||(a[14]=[n("Seth Kenlon",-1)])]),_:1}),a[19]||(a[19]=n(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[15]||(a[15]=[n("lujun9972",-1)])]),_:1}),a[20]||(a[20]=n(" 译者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[16]||(a[16]=[n("geekpi",-1)])]),_:1}),a[21]||(a[21]=n(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[17]||(a[17]=[n("wxy",-1)])]),_:1})]),s("p",null,[a[24]||(a[24]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[22]||(a[22]=[n("LCTT",-1)])]),_:1}),a[25]||(a[25]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...a[23]||(a[23]=[n("Linux中国",-1)])]),_:1}),a[26]||(a[26]=n(" 荣誉推出",-1))])])}const C=p(u,[["render",k]]);export{y as __pageData,C as default};
